1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import type {SessionStore} from '../../types/sessionStore.js';
5	import {ErrorCodes} from '../../types/messages.js';
6	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
55	    }
56	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
57	    // A history request is not a turn: answered here, outside the lock, so it never queues behind a streaming answer.
58	    if (validation.valid && validation.data.type === 'list_sessions') {
59	      const message: ListSessionsMessage = validation.data;
60	      return wsErrorHandler(ws, () => handleListSessions(ws, session, sessionStore, message));
61	    }
62	    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
63	  };
64	}
65	
66	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
67	async function answerInTurn(
68	  ws: WebSocket,
69	  session: ChatSession,
70	  orchestrator: ChatOrchestrator,
71	  validation: ValidationResult,
72	  signal: AbortSignal | undefined
73	): Promise<void> {
74	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
75	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
76	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
77	    return;
78	  }
79	  const startedAt = Date.now();
80	  try {
81	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
82	  } finally {
83	    endTurn(ws, session, signal, startedAt);
84	  }
85	}
86	
87	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
88	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
89	  if (signal?.aborted) {
90	    log.info('message', 'turn abandoned: its socket closed', {
91	      sessionId: session.sessionId,
92	      elapsedMs: Date.now() - startedAt,
93	    });
94	    return;
95	  }
96	  sendStreamEnd(ws);
97	}
98	
99	async function answerUserMessage(
100	  ws: WebSocket,
101	  session: ChatSession,
102	  orchestrator: ChatOrchestrator,
103	  validation: ValidationResult,
104	  signal: AbortSignal | undefined
105	): Promise<void> {
106	  const message = validation.valid ? validation.data : undefined;
107	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
108	  answerFrame(ws, validation);
109	}
110	
111	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
112	  if (!validation.valid) {
113	    log.warn('message', 'validation failed', {error: validation.error});
114	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
115	    return;
116	  }
117	
118	  const message = validation.data;
119	  if (message.type === 'ping') handlePing(ws, message.timestamp);
120	}
121	
122	// The user listed is the connection's own, read from the session: a frame naming another user lists no one else.
123	async function handleListSessions(
124	  ws: WebSocket,
125	  session: ChatSession,
126	  sessionStore: SessionStore | undefined,
127	  message: ListSessionsMessage
128	): Promise<void> {
129	  if (!sessionStore?.listFor) {
130	    sendSessionList(ws, []);
131	    return;
132	  }
133	  try {
134	    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
135	    sendSessionList(ws, summaries);
136	  } catch (error) {
137	    const detail = error instanceof Error ? error.message : 'Unknown error';
138	    log.error('ws', 'listing sessions failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
139	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
140	  }
141	}
142	
143	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
144	function isUserMessageFrame(rawMessage: unknown): boolean {
145	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
146	}
147	
148	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
149	  try {
150	    await action();
151	  } catch (error) {
152	    const message = error instanceof Error ? error.message : 'Unknown error';
153	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
154	    log.error('message', 'handling error', {error: message, code});
155	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
156	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
157	      return;
158	    }
159	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
160	  }
161	}
162	
163	async function handleUserMessage(
164	  ws: WebSocket,
165	  session: ChatSession,
166	  orchestrator: ChatOrchestrator,
167	  content: string,
168	  signal: AbortSignal | undefined
169	): Promise<void> {
170	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
171	
172	  const userEntry = createUserEntry(content);
173	  const userIndex = appendEntry(session, userEntry);
174	  sendUpsert(ws, userIndex, userEntry);
175	
176	  const parser = new ThinkingTagParser();
177	  const state: StreamState = {
178	    thinkingIndex: null,
179	    assistantIndex: null,
180	    suppressOutput: false,
181	    sentAssistantIndices: [],
182	  };
183	
184	  let textChunkCount = 0;
185	
186	  try {
187	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
188	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
189	      if (signal?.aborted) break;
190	      textChunkCount = logChunk(chunk, textChunkCount);
191	      processChunk(ws, session, state, parser, chunk);
192	    }
193	  } finally {
194	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
195	    flushHeldText(ws, session, state, parser);
196	    closeCutOff(ws, session, state, 'thinkingIndex');
197	    closeCutOff(ws, session, state, 'assistantIndex');
198	  }
199	
200	  if (textChunkCount > 0) {
201	    log.debug('stream', `received ${textChunkCount} text chunks`);
202	  }
203	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
204	}
205	
206	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
207	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
208	  if (chunk.type === 'text') return textChunkCount + 1;
209	
210	  if (textChunkCount > 0) {
211	    log.debug('stream', `received ${textChunkCount} text chunks`);
212	  }
213	
214	  if (chunk.type === 'tool_result') {
215	    log.debug('stream', 'tool_result chunk', {
216	      messageCount: chunk.clientMessages.length,
217	      types: chunk.clientMessages.map(m => m.type),
218	    });
219	    return 0;
220	  }
221	
222	  log.debug('stream', 'chunk', {type: chunk.type});
223	  return 0;
224	}
225	
226	function processChunk(
227	  ws: WebSocket,
228	  session: ChatSession,
229	  state: StreamState,
230	  parser: ThinkingTagParser,
231	  chunk: MessageChunk
232	): void {
233	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
234	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
235	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
236	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
237	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
238	}
239	
240	function processTextChunk(
241	  ws: WebSocket,
242	  session: ChatSession,
243	  state: StreamState,
244	  parser: ThinkingTagParser,
245	  text: string
246	): void {
247	  const segments = parser.push(text);
248	  for (const segment of segments) {
249	    handleTextSegment(ws, session, state, segment);
250	  }
251	}
252	
253	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
254	  if (segment.type === 'thinking') {
255	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
256	    return;
257	  }
258	  commitAndClear(ws, session, state, 'thinkingIndex');
259	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
260	}
261	
262	function streamSegment(
263	  ws: WebSocket,
264	  session: ChatSession,
265	  state: StreamState,
266	  key: StateIndexKey,
267	  createEntry: EntryFactory,
268	  content: string
269	): void {
270	  const isNew = initSegment(session, state, key, createEntry);
271	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
272	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
273	  appendDelta(session, state[key]!, content);
274	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
275	}
276	
277	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
278	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
279	  markSuppressed(session, index);
280	  sendSkip(ws, index);
281	}
282	
283	function markSuppressed(session: ChatSession, index: number): void {
284	  const entry = session.entries[index];
285	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
286	}
287	
288	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
289	  if (state[key] !== null) return false;
290	  state[key] = appendEntry(session, createEntry());
291	  return true;
292	}
293	
294	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
295	  const index = state[key];
296	  if (index === null) return;
297	
298	  commitEntry(session, index);
299	  state[key] = null;
300	
301	  // Only what the client received can be retracted, and only assistant entries.
302	  if (state.suppressOutput) return;
303	
304	  sendCommit(ws, index);
305	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
306	}
307	
308	function processToolUseChunk(
309	  ws: WebSocket,
310	  session: ChatSession,
311	  toolCall: {name: string; input: Record<string, unknown>}
312	): void {
313	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
314	  const toolIndex = appendEntry(session, toolEntry);
315	  sendUpsert(ws, toolIndex, toolEntry);
316	}
317	
318	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
319	  for (const msg of clientMessages) {
320	    log.debug('stream', 'forwarding client message to frontend', {
321	      type: msg.type,
322	      index: 'index' in msg ? msg.index : undefined,
323	    });
324	    sendJson(ws, msg);
325	  }
326	}
327	
328	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
329	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
330	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
331	  commitOpenEntries(ws, session, state);
332	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
333	
334	  for (const idx of state.sentAssistantIndices) {
335	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
336	    markSuppressed(session, idx);
337	  }
338	
339	  state.sentAssistantIndices = [];
340	  state.suppressOutput = true;
341	}
342	
343	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
344	  flushHeldText(ws, session, state, parser);
345	  commitOpenEntries(ws, session, state);
346	}
347	
348	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
349	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
350	  for (const segment of parser.flush()) {
351	    handleTextSegment(ws, session, state, segment);
352	  }
353	}
354	
355	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
356	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
357	  const index = state[key];
358	  if (index === null) return;
359	  markTruncated(session, index);
360	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
361	  commitAndClear(ws, session, state, key);
362	}
363	
364	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
365	  commitAndClear(ws, session, state, 'thinkingIndex');
366	  commitAndClear(ws, session, state, 'assistantIndex');
367	}
368	
369	function handlePing(ws: WebSocket, timestamp: number): void {
370	  ws.send(JSON.stringify({type: 'pong', timestamp}));
371	}
