    {
      frame: {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
      answered: {valid: false, error: momentError},
    },
  ];

  expect(cases.map(({frame}) => validateMessage(frame))).toEqual(cases.map(({answered}) => answered));
});

