import {validateMessage} from './validation.js';
import type {ValidationResult} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_sessions with an integer limit and a before cursor, and rejects either malformed', () => {
    const cursor = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's3'};

    expect(validateMessage({type: 'list_sessions', limit: 10, before: cursor, userId: 'u2'})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before: cursor},
    });
    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
    expect(validateMessage({type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's3'}})).toEqual({
      valid: true,
      data: {type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's3'}},
    });

    const limitError = 'list_sessions limit must be an integer of 0 or more';
    const cursorError = 'list_sessions before must be an object of sessionId and updatedAt';
    const rejected: Array<{frame: unknown; error: string}> = [
      {frame: {type: 'list_sessions', limit: 'ten'}, error: limitError},
      {frame: {type: 'list_sessions', limit: -1}, error: limitError},
      {frame: {type: 'list_sessions', limit: 1.5}, error: limitError},
      {frame: {type: 'list_sessions', before: 'not-an-object'}, error: cursorError},
      {
        frame: {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
        error: 'list_sessions before sessionId must be a string of 1 to 128 characters',
      },
      {
        frame: {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
        error: 'list_sessions before sessionId must be a string of 1 to 128 characters',
      },
      {
        frame: {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
        error: 'list_sessions before updatedAt must be a valid timestamp',
