1	import type {AddressInfo} from 'node:net';
2	import {WebSocket} from 'ws';
3	import type {Express} from 'express';
4	import {createServer} from './createServer.js';
5	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
6	import {answeringOrchestrator, delegatingTo, listedConversation, socketSandbox} from './wsTestSupport.js';
7	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
8	import type {SessionCursor, SessionListOptions, SessionStore} from '../types/sessionStore.js';
9	import {setLogger} from '../shared/logger.js';
10	
11	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
12	
13	interface Frame {
14	  type: string;
15	  sessionId?: string;
16	  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
17	  code?: string;
18	  message?: string;
19	}
20	
21	const {servers, clients, drain} = socketSandbox();
22	const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
23	
24	beforeEach(() => {
25	  logLines.length = 0;
26	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
27	    void logLines.push({level, category, message, fields});
28	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
29	});
30	
31	afterEach(async () => {
32	  await drain();
33	  setLogger();
34	});
35	
36	const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
37	  const hal = createServer({
38	    app: (() => undefined) as unknown as Express,
39	    wsAuth: async () => ({id: userId}),
40	    sessionStore: store,
41	    orchestrator: answeringOrchestrator,
42	  });
43	  await hal.start(0);
44	  servers.push(hal);
45	  const {port} = hal.server.address() as AddressInfo;
46	  return `ws://127.0.0.1:${port}/hal/ws`;
47	};
48	
49	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
50	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
51	  clients.push(client);
52	  const frames: Frame[] = [];
53	  let connected: Frame = {type: ''};
54	  await new Promise<void>(resolve => {
55	    client.on('message', raw => {
56	      const frame = JSON.parse(String(raw)) as Frame;
57	      if (frame.type === 'pong') {
58	        resolve();
59	        return;
60	      }
61	      if (frame.type !== 'connected') {
62	        frames.push(frame);
63	        return;
64	      }
65	      connected = frame;
66	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
67	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
68	    });
69	  });
70	  return {connected, frames};
71	};
72	
73	describe('listing conversations over the WebSocket protocol', () => {
74	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
75	    const inner = new InMemorySessionStore();
76	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
77	    const store: SessionStore = {
78	      ...delegatingTo(inner),
79	      listFor: (userId, options) => {
80	        seen.push({userId, options});
81	        return [listedConversation.summary];
82	      },
83	    };
84	    const url = await startEngine(store, 'u1');
85	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
86	
87	    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
88	
89	    expect({seen, frames}).toEqual({
90	      seen: [{userId: 'u1', options: {limit: 10, before}}],
91	      frames: [{type: 'session_list', sessions: [listedConversation.onWire]}],
92	    });
93	  });
94	
95	  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
96	    const inner = new InMemorySessionStore();
97	    const withoutList = await startEngine(delegatingTo(inner));
98	    const failingList = await startEngine({
99	      ...delegatingTo(inner),
100	      listFor: () => Promise.reject(new Error('database offline')),
101	    });
102	
103	    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
104	    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});
105	
106	    expect({
107	      unimplemented: unimplemented.frames,
108	      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
109	      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
110	    }).toEqual({
111	      unimplemented: [{type: 'session_list', sessions: []}],
112	      failed: [{type: 'error', code: 'SERVER_ERROR'}],
113	      logged: [
114	        {
115	          level: 'error',
116	          category: 'ws',
117	          message: expect.any(String),
118	          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
119	        },
120	      ],
121	    });
122	  });
123	
124	  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
125	    const inner = new InMemorySessionStore();
126	    let calls = 0;
127	    const store: SessionStore = {
128	      ...delegatingTo(inner),
129	      listFor: () => {
130	        calls += 1;
131	        return [];
132	      },
133	    };
